/** Řádky → místa pro planItinerary. */
export const places = (rows) => rows.map(([id, name, lat, lon, category, score, sitelinks, x = {}]) => ({
  id, name, lat, lon, category, score, sitelinks, ...(x.u ? { unesco: true } : {}), ...(x.e ? { eatery: true } : {}), ...(x.i ? { island: true } : {}),
  ...(x.v ? { visitMin: x.v } : {}), ...(x.inc ? { includes: x.inc } : {}),
}));
